<?php
namespace App\Http\Controllers\Api;
use App\Http\Requests\SystemSettingRequest; use App\Http\Resources\SystemSettingResource; use App\Models\SystemSetting; use App\Repositories\EnterpriseRepository; use App\Services\EnterpriseService; use Illuminate\Http\Request;
class SystemSettingController extends BaseApiController { private EnterpriseService $service; public function __construct(){ $this->service=new EnterpriseService(new EnterpriseRepository(new SystemSetting)); } public function index(Request $r){$this->authorize('viewAny',SystemSetting::class);return $this->respondWithResource(SystemSettingResource::collection($this->service->paginate($r->validate(['company_id'=>['nullable','exists:companies,id'],'per_page'=>['nullable','integer'],'sort'=>['nullable','string'],'direction'=>['nullable','in:asc,desc']]))),'Settings retrieved successfully.');} public function store(SystemSettingRequest $r){return $this->respondSuccess(new SystemSettingResource($this->service->create($r->validated())),'Setting created successfully.',201);} public function show(SystemSetting $systemSetting){return $this->respondSuccess(new SystemSettingResource($systemSetting));} public function update(SystemSettingRequest $r,SystemSetting $systemSetting){return $this->respondSuccess(new SystemSettingResource($this->service->update($systemSetting,$r->validated())),'Setting updated successfully.');} public function destroy(SystemSetting $systemSetting){$this->service->delete($systemSetting);return $this->respondSuccess(null,'Setting deleted successfully.');} }
